use std::fs::File;
use std::io::{self, BufRead, BufReader};

/// Итератор по строкам большого файла, который не загружает весь файл в память.
///
/// Данный итератор читает файл побайтово (через буферизированный ввод) и
/// возвращает строки одна за другой. Каждая строка — это `String`, который
/// выделяется под текущую строку и освобождается после её использования.
/// Таким образом, в памяти одновременно находится только одна строка (плюс
/// небольшой буфер чтения), что позволяет обрабатывать файлы любого размера.
///
/// # Пример использования
///
/// ```no_run
/// use std::fs::File;
/// use std::io::BufReader;
///
/// let file = File::open("big_file.txt").unwrap();
/// let reader = BufReader::new(file);
///
/// for line in reader.lines() {
///     let line = line.unwrap();
///     println!("{}", line);
/// }
/// ```
pub struct LineIterator<R: BufRead> {
    /// Буферизированный источник данных (например, `BufReader<File>`).
    /// Хранит внутренний буфер для эффективного чтения из ОС.
    reader: R,
    /// Флаг, указывающий, достигнут ли конец файла.
    /// После первого вызова `next()`, который вернул `None`, все последующие
    /// вызовы также будут возвращать `None` без обращения к источнику.
    eof_reached: bool,
}

impl<R: BufRead> LineIterator<R> {
    /// Создаёт новый итератор по строкам из заданного буферизированного источника.
    ///
    /// # Аргументы
    ///
    /// * `reader` — любой тип, реализующий трейт `BufRead` (например,
    ///   `BufReader<File>`, `BufReader<StdinLock>`, `Cursor<Vec<u8>>` и т.д.).
    ///
    /// # Возвращаемое значение
    ///
    /// Новый экземпляр `LineIterator`, готовый к итерации.
    pub fn new(reader: R) -> Self {
        LineIterator {
            reader,
            eof_reached: false,
        }
    }
}

impl<R: BufRead> Iterator for LineIterator<R> {
