/// <summary>
/// Выполняет асинхронное действие с повторными попытками в случае сбоя.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая Task&lt;int&gt;, которую нужно выполнить.</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат выполнения действия (int), если оно завершилось успешно.</returns>
/// <exception cref="InvalidOperationException">Бросается, если все попытки исчерпаны и исключение не было перехвачено (теоретически недостижимая ситуация).</exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для перебора всех возможных попыток выполнения действия
    for (var i = 0; i < attempts; i++)
    {
        try 
        {
            // Пытаемся выполнить переданное асинхронное действие
            // Если действие завершается успешно, сразу возвращаем результат
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Перехватываем только исключения HttpRequestException
            // Условие "when (i < attempts - 1)" гарантирует, что мы делаем паузу
            // только если это не последняя попытка (чтобы не ждать после финального сбоя)

            // Вычисляем задержку с экспоненциальным бэкоффом:
            // 200 мс * 2^i (например: 200мс, 400мс, 800мс, ...)
            // Это помогает снизить нагрузку на сервер при временных сбоях сети
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Эта строка теоретически недостижима, так как:
    // - Если action() выполнилась успешно, метод уже вернул значение выше
    // - Если произошло исключение HttpRequestException на последней попытке,
    //   оно будет проброшено наружу (условие when не сработает)
    // Однако компилятор требует явного выхода из метода, поэтому бросаем исключение
    throw new InvalidOperationException("unreachable");
}
