/**
 * Создаёт дебаунс-обёртку для переданной функции.
 * Дебаунс откладывает выполнение функции до тех пор, пока не прекратятся вызовы в течение заданного времени (ms).
 * 
 * @param fn - Функция, которую нужно обернуть в дебаунс.
 * @param ms - Задержка в миллисекундах, после которой функция будет выполнена, если новых вызовов не было.
 * @returns Обёрнутая функция с теми же параметрами и типом возвращаемого значения, что и оригинальная.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Изначально она не определена, так как таймер ещё не был создан.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная функция `fn`.
  return (...args: Parameters<T>) => {
    // Если предыдущий таймер ещё существует (т.е. функция была вызвана ранее и таймер не истёк),
    // то отменяем его, чтобы сбросить отсчёт времени.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер на задержку `ms` миллисекунд.
    // По истечении этого времени будет вызвана исходная функция `fn` с последними переданными аргументами `args`.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

